 10	/**
 11	 * The rate plans the inn sells. Each one knows the three things that set it apart: how to price a
 12	 * stay, who may use it (a stay the plan refuses cannot be booked), and how much comes back when a
 13	 * confirmed reservation is cancelled. A new plan is a new constant here, with those three answers;
 14	 * nothing else needs to change.
 15	 */
 16	public enum RatePlan {
 17	
 18	    /** Full price; everything comes back on cancellation. */
 19	    STANDARD {
 20	        @Override
 21	        Price price(PricingContext context) {
 22	            return nightlyPrice(context, BigDecimal.ZERO);
 23	        }
 24	
 25	        @Override
 26	        BigDecimal refund(BigDecimal amountPaid) {
 27	            return amountPaid;
 28	        }
 29	    },
 30	
 31	    /** 15% off the nights, but nothing comes back on cancellation. */
 32	    NON_REFUNDABLE {
 33	        @Override
 34	        Price price(PricingContext context) {
 35	            return nightlyPrice(context, new BigDecimal("0.15"));
 36	        }
 37	
 38	        @Override
 39	        BigDecimal refund(BigDecimal amountPaid) {
 40	            return cents(BigDecimal.ZERO);
 41	        }
 42	    },
 43	
 44	    /** A company deal: the discount depends on the company code, which the guest must supply. */
 45	    CORPORATE {
 46	        @Override
 47	        void validate(PricingContext context) {
 48	            companyDiscount(context.companyCode());
 49	        }
 50	
 51	        @Override
 52	        Price price(PricingContext context) {
 53	            return nightlyPrice(context, companyDiscount(context.companyCode()));
 54	        }
 55	
 56	        @Override
 57	        BigDecimal refund(BigDecimal amountPaid) {
 58	            return amountPaid;
 59	        }
 60	    },
 61	
 62	    /** Friday to the next Sunday, two nights, at a flat price all year; half comes back on cancellation. */
 63	    WEEKEND_PACKAGE {
 64	        @Override
 65	        void validate(PricingContext context) {
 66	            boolean fridayToSunday = context.checkIn().getDayOfWeek() == DayOfWeek.FRIDAY
 67	                    && context.checkOut().equals(context.checkIn().plusDays(2));
 68	            if (!fridayToSunday) {
 69	                throw new HotelException(
 70	                        ErrorCode.INVALID_REQUEST,
 71	                        "the weekend package is Friday to the next Sunday, exactly two nights");
 72	            }
 73	        }
 74	
 75	        @Override
 76	        Price price(PricingContext context) {
 77	            BigDecimal packagePrice = cents(WEEKEND_PACKAGE_PRICES.get(context.room().type()));
 78	            return new Price(2, packagePrice, cents(BigDecimal.ZERO), packagePrice);
 79	        }
 80	
 81	        @Override
 82	        BigDecimal refund(BigDecimal amountPaid) {
 83	            return cents(amountPaid.multiply(new BigDecimal("0.5")));
 84	        }
 85	    },
 86	
 87	    /** Seven nights or more: 10% off the nights (high season still counts); everything comes back. */
 88	    LONG_STAY {
 89	        @Override
 90	        void validate(PricingContext context) {
 91	            if (PriceCalculator.nights(context.checkIn(), context.checkOut()) < LONG_STAY_MIN_NIGHTS) {
 92	                throw new HotelException(
 93	                        ErrorCode.INVALID_REQUEST,
 94	                        "the long-stay plan needs at least " + LONG_STAY_MIN_NIGHTS + " nights");
 95	            }
 96	        }
 97	
 98	        @Override
 99	        Price price(PricingContext context) {
100	            return nightlyPrice(context, new BigDecimal("0.10"));
101	        }
102	
103	        @Override
104	        BigDecimal refund(BigDecimal amountPaid) {
105	            return amountPaid;
106	        }
107	    };
108	
109	    private static final Map<String, BigDecimal> CORPORATE_DISCOUNTS = Map.of(
110	            "TECNOSUL", new BigDecimal("0.12"),
111	            "AGROVALE", new BigDecimal("0.18"),
112	            "FARMAVIDA", new BigDecimal("0.25"));
113	
114	    private static final Map<RoomType, BigDecimal> WEEKEND_PACKAGE_PRICES = Map.of(
115	            RoomType.STANDARD, new BigDecimal("520.00"),
116	            RoomType.DELUXE, new BigDecimal("820.00"),
117	            RoomType.SUITE, new BigDecimal("1200.00"));
118	
119	    private static final int LONG_STAY_MIN_NIGHTS = 7;
120	
121	    /** Whether this plan accepts the stay. The default plan takes any stay; others may refuse. */
122	    void validate(PricingContext context) {}
123	
124	    /** The price of the stay under this plan. */
125	    abstract Price price(PricingContext context);
126	
127	    /** What comes back when a confirmed reservation on this plan is cancelled. */
128	    abstract BigDecimal refund(BigDecimal amountPaid);
129	
130	    /** The nights at the room's rate (high season included), with a flat discount on the sum. */
131	    private static Price nightlyPrice(PricingContext context, BigDecimal discountRate) {
132	        int nights = PriceCalculator.nights(context.checkIn(), context.checkOut());
133	        BigDecimal subtotal = PriceCalculator.nightlySubtotal(context.room(), context.checkIn(), context.checkOut());
134	        BigDecimal discount = cents(subtotal.multiply(discountRate));
135	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
136	    }
137	
138	    private static BigDecimal companyDiscount(String companyCode) {
139	        BigDecimal discount = companyCode == null ? null : CORPORATE_DISCOUNTS.get(companyCode);
140	        if (discount == null) {
141	            throw new HotelException(
142	                    ErrorCode.INVALID_REQUEST, "the corporate plan needs a known company code");
143	        }
144	        return discount;
145	    }
146	}
