151	
152	/**
153	 * What a rate plan needs to judge a stay and put a price on it: the room, the dates, and the company
154	 * code (only the corporate plan reads it; the others ignore it, so it may be null).
155	 */
156	public record PricingContext(Room room, LocalDate checkIn, LocalDate checkOut, String companyCode) {
157	}
158	package hotel.reservations;
159	
160	import hotel.rooms.Room;
161	import java.math.BigDecimal;
162	import java.math.RoundingMode;
163	import java.time.LocalDate;
164	import java.time.Month;
165	import java.time.temporal.ChronoUnit;
166	
167	/**
168	 * Prices a stay by asking its rate plan. The plan decides the price; this class holds the nightly
169	 * arithmetic the plans share: every night costs the room's nightly rate, plus the high-season
170	 * surcharge on high-season nights. Money is rounded to cents (half-even) at every step.
171	 */
172	public final class PriceCalculator {
173	
174	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
175	
176	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
177	        return calculate(new PricingContext(room, checkIn, checkOut, null), ratePlan);
178	    }
179	
180	    public Price calculate(PricingContext context, RatePlan ratePlan) {
181	        return ratePlan.price(context);
182	    }
183	
184	    static int nights(LocalDate checkIn, LocalDate checkOut) {
185	        return (int) ChronoUnit.DAYS.between(checkIn, checkOut);
186	    }
187	
188	    /** The nights of a stay at the room's rate, with the high-season surcharge on high-season nights. */
189	    static BigDecimal nightlySubtotal(Room room, LocalDate checkIn, LocalDate checkOut) {
190	        BigDecimal subtotal = cents(BigDecimal.ZERO);
191	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
192	            subtotal = subtotal.add(nightPrice(room, night));
193	        }
194	        return subtotal;
195	    }
196	
197	    static BigDecimal nightPrice(Room room, LocalDate night) {
198	        BigDecimal nightlyRate = room.nightlyRate();
199	        if (isHighSeason(night)) {
200	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
201	        }
202	        return cents(nightlyRate);
203	    }
204	
205	    /** High season: from December 15 to the end of February, and the whole of July. */
206	    static boolean isHighSeason(LocalDate date) {
207	        Month month = date.getMonth();
208	        return month == Month.JANUARY
209	                || month == Month.FEBRUARY
210	                || month == Month.JULY
211	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
212	    }
213	
214	    static BigDecimal cents(BigDecimal value) {
215	        return value.setScale(2, RoundingMode.HALF_EVEN);
216	    }
217	}

