  1	package hotel.reservations;
  2	
  3	import hotel.documents.ReservationReceipt;
  4	import hotel.messages.EmailSender;
  5	import hotel.rooms.Room;
  6	import hotel.rooms.Rooms;
  7	
  8	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
  9	public final class ReservationService {
 10	
 11	    static final String HOTEL_NAME = "Pousada Maré Alta";
 12	
 13	    private final Rooms rooms;
 14	    private final ReservationStore store;
 15	    private final PriceCalculator priceCalculator;
 16	    private final EmailSender emailSender;
 17	
 18	    public ReservationService(
 19	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
 20	        this.rooms = rooms;
 21	        this.store = store;
 22	        this.priceCalculator = priceCalculator;
 23	        this.emailSender = emailSender;
 24	    }
 25	
 26	    public synchronized Reservation create(NewReservation request) {
 27	        if (!request.checkOut().isAfter(request.checkIn())) {
 28	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
 29	        }
 30	        if (request.guests() < 1) {
 31	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
 32	        }
 33	        Room room = rooms.find(request.roomNumber())
 34	                .orElseThrow(() -> new HotelException(
 35	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
 36	        if (request.guests() > room.capacity()) {
 37	            throw new HotelException(
 38	                    ErrorCode.CAPACITY_EXCEEDED,
 39	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
 40	        }
 41	        PricingContext pricing =
 42	                new PricingContext(room, request.checkIn(), request.checkOut(), request.companyCode());
 43	        request.ratePlan().validate(pricing);
 44	        boolean roomTaken = store.all().stream()
 45	                .filter(existing -> existing.status() != ReservationStatus.CANCELLED)
 46	                .anyMatch(existing -> existing.overlaps(room.number(), request.checkIn(), request.checkOut()));
 47	        if (roomTaken) {
 48	            throw new HotelException(
 49	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
 50	        }
 51	        Price price = priceCalculator.calculate(pricing, request.ratePlan());
 52	        Reservation reservation = new Reservation(store.nextId(), request, price);
 53	        store.save(reservation);
 54	        return reservation;
 55	    }
 56	
 57	    public Reservation find(long reservationId) {
 58	        return store.find(reservationId)
 59	                .orElseThrow(() -> new HotelException(
 60	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
 61	    }
 62	
 63	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
 64	    public synchronized Reservation confirm(long reservationId) {
 65	        Reservation reservation = find(reservationId);
 66	        if (reservation.status() != ReservationStatus.PENDING) {
 67	            throw notAllowed(reservation, "confirm");
 68	        }
 69	        reservation.confirmPayment();
 70	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
 71	        emailSender.send(
 72	                reservation.guest().email(),
 73	                "Reserva confirmada - " + HOTEL_NAME,
 74	                confirmationEmailBody(reservation, receipt));
 75	        return reservation;
 76	    }
 77	
 78	    /**
 79	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
 80	     * reservation was never paid, so nothing comes back).
 81	     */
 82	    public synchronized Reservation cancel(long reservationId) {
 83	        Reservation reservation = find(reservationId);
 84	        if (reservation.status() != ReservationStatus.PENDING
 85	                && reservation.status() != ReservationStatus.CONFIRMED) {
 86	            throw notAllowed(reservation, "cancel");
 87	        }
 88	        reservation.cancel(reservation.ratePlan().refund(reservation.amountPaid()));
 89	        return reservation;
 90	    }
 91	
 92	    public synchronized Reservation checkIn(long reservationId) {
 93	        Reservation reservation = find(reservationId);
 94	        if (reservation.status() != ReservationStatus.CONFIRMED) {
 95	            throw notAllowed(reservation, "check in");
 96	        }
 97	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
 98	        return reservation;
 99	    }
100	
101	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
102	    public synchronized ReservationReceipt checkOut(long reservationId) {
103	        Reservation reservation = find(reservationId);
104	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
